widget.prelude:
class _Counted(list):
    reads = 0

    def __getitem__(self, i):
        _Counted.reads += 1
        return list.__getitem__(self, i)

    def __iter__(self):
        _Counted.reads += len(self)
        return list.__iter__(self)


def update_reads(n, updates):
    # how many times apply_ranges reads the updates list
    _Counted.reads = 0
    apply_ranges(n, _Counted(updates))
    return _Counted.reads


def checksum(values):
    return sum(i * x for i, x in enumerate(values)) % 1000000007

widget.solution:
def max_coverage(n, intervals):
    d = [0] * (n + 1)
    for l, r in intervals:
        d[l] += 1
        d[r + 1] -= 1
    best = run = 0
    for i in range(n):
        run += d[i]
        best = max(best, run)
    return best
